-- A person's patrons: other people on the same sheet, each named at most once. A person shows
-- their patrons' names and their backing (the patrons' due-totals added up, n/a ones skipped).
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (patron_id <> person_id),
    CONSTRAINT person_patron_once UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import net.officefloor.hq.app.history.HistoryListener;

/** A person named as another person's patron, on the same sheet. */
@Entity
@EntityListeners(HistoryListener.class)
@Table(name = "person_patron")
public class PersonPatron {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "patron_id", nullable = false)
    private Long patronId;

    protected PersonPatron() {
    }

    public PersonPatron(String sheetId, Long personId, Long patronId) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.patronId = patronId;
    }

    public Long getId() {
        return id;
    }

    public Long getPersonId() {
        return personId;
    }

    public Long getPatronId() {
        return patronId;
    }

    public String getSheetId() {
        return sheetId;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PersonPatronRepository extends JpaRepository<PersonPatron, Long> {

    /** The sheet's patrons, in the order they were named. */
    List<PersonPatron> findBySheetIdOrderByIdAsc(String sheetId);

    /** The person's patrons, in the order they were named. */
    List<PersonPatron> findByPersonIdOrderByIdAsc(Long personId);

    /** The people naming the patron, in the order they named them. */
    List<PersonPatron> findByPatronIdOrderByIdAsc(Long patronId);

    boolean existsByPersonIdAndPatronId(Long personId, Long patronId);
}
